              if x != bg and x != line_color}
    if not colors:
        return g
    obj_color = max(colors, key=lambda x: sum(row.count(x) for row in g))
    cells = [(r, c) for r in range(h) for c in range(w)
             if g[r][c] == obj_color]
    if not cells:
        return g

    old_top = min(r for r, c in cells)
    old_bottom = max(r for r, c in cells)

    if old_bottom < line_r:
        shift = line_r - 1 - old_bottom
        new_cells = [(r + shift, c) for r, c in cells]
        marker_r = min(r for r, c in new_cells) - 1
    elif old_top > line_r:
        shift = line_r + 1 - old_top
        new_cells = [(r + shift, c) for r, c in cells]
        marker_r = max(r for r, c in new_cells) + 1
    else:
        return g

    for r, c in cells:
        g[r][c] = bg
    for r, c in new_cells:
        g[r][c] = obj_color
    if 0 <= marker_r < h:
